/**
 * Test fixture, not a real plugin. It stands in for a plugin whose only broken
 * rule fires on syntax the bundled corpus does not contain, so the corpus board
 * reports it clean while a repo that uses dynamic import sees it crash.
 *
 * Installed here at 1.2.3 while the lockfile says 1.0.0, which is what makes it
 * usable for checking that node_modules wins.
 */
import { ESLint } from 'eslint';

const removedOnTen = Number.parseInt(ESLint.version, 10) >= 10;

export default {
  meta: { name: 'eslint-plugin-fixture-lazy-import', version: '1.2.3' },
  rules: {
    'no-lazy-import': {
      meta: { type: 'problem', schema: [] },
      create(context) {
        return {
          ImportExpression(node) {
            if (removedOnTen) {
              throw new TypeError("Cannot read properties of undefined (reading 'importAttributes')");
            }
            context.report({ node, message: 'dynamic import' });
          },
        };
      },
    },
    'sorted-imports': {
      meta: { type: 'suggestion', schema: [] },
      create(context) {
        return {
          ImportDeclaration(node) {
            if (node.specifiers.length > 3) context.report({ node, message: 'too many specifiers' });
          },
        };
      },
    },
  },
};
